38	// Linker symbols from qemu_cfg.o (obj_sc/qemu.cfg), see print_qemu_config().
39	// The same config.inc distilled to a QEMU -readconfig cfg at build time
40	// (cmake/VerilatorHelpers.cmake); empty when no converter was configured.
41	extern char _binary_qemu_cfg_start;
42	extern char _binary_qemu_cfg_end;
