66	// Emit the andes-sim engine descriptor (see docs/engine_interface.md). This is
67	// the self-describe half of the framework's hot-plug contract: andes-sim runs
68	// `sim_<cfg> --describe`, parses this JSON, and can then drive the binary with
69	// no per-engine code. vlen/xlen come from the same embedded config.inc blob
70	// that --print-config dumps; the config name comes from VSIM_CPU_PYMODULE_NAME.
71	static void describe_engine()
72	{
73	  std::string cfg = VSIM_CPU_PYMODULE_NAME;  // "simulator_<cfg>"
74	  const std::string prefix = "simulator_";
75	  if (cfg.starts_with(prefix))
76	    cfg = cfg.substr(prefix.size());
77	
78	  const std::string_view blob(&_binary_config_inc_start,
79	                              static_cast<size_t>(&_binary_config_inc_end
80	                                                  - &_binary_config_inc_start));
81	  auto scan_int = [blob](std::string_view key) -> long {
82	    size_t pos = blob.find(key);
83	    if (pos == std::string_view::npos)
84	      return 0;
85	    pos += key.size();
86	    while (pos < blob.size() && (blob[pos] < '0' || blob[pos] > '9'))
87	      ++pos;
88	    long v = 0;
89	    while (pos < blob.size() && blob[pos] >= '0' && blob[pos] <= '9')
90	      v = v * 10 + (blob[pos++] - '0');
91	    return v;
92	  };
93	  const long vlen = scan_int("NDS_VLEN");
94	  const long dlen = scan_int("NDS_DLEN");
95	  const long elen = scan_int("NDS_ELEN");
96	  const long xlen = scan_int("NDS_XLEN");
97	
98	  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
99	  // placeholders out of fmt's brace parser.
100	  std::string json;
101	  json += "{\n";
102	  json += "  \"id\": \"verilator:" + cfg + "\",\n";
103	  json += "  \"type\": \"verilator\",\n";
104	  json += "  \"kind\": \"cycle-accurate\",\n";
105	  json += "  \"vlen\": " + std::to_string(vlen) + ", \"dlen\": "
106	          + std::to_string(dlen) + ", \"elen\": " + std::to_string(elen)
107	          + ", \"xlen\": " + std::to_string(xlen) + ",\n";
108	  json += "  \"triggers\": [\"csr\", \"pc\"],\n";
109	  json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
110	  json += "  \"state\": [\"resume\", \"drain\"],\n";
111	  // Andes custom CSRs this core actually implements (from its config.inc).
112	  // The driver uses this to skip --verify on CSRs the engine lacks, mirroring
113	  // the resume/drain gating in ResumeDriver/StateDrain (single binder).
114	  const std::vector<std::string> andes_csrs =
115	      hybrid::supported_andes_csr_names(hybrid::andes_caps_from_config());
116	  json += "  \"andes_csrs\": [";
117	  for (size_t i = 0; i < andes_csrs.size(); ++i)
118	    json += (i ? ", \"" : "\"") + andes_csrs[i] + "\"";
119	  json += "],\n";
120	  json += "  \"invoke\": {\n";
121	  json += "    \"standalone\": [\"{bin}\", \"{elf}\"],\n";
122	  json += "    \"accurate-leg\": [\"{bin}\", \"{elf}\", "
123	          "\"--resume-from-qemu\", \"{state_in}\", "
124	          "\"--handoff-out\", \"{state_out}\", "
125	          "\"--shared-mem-path\", \"{mmap}\", "
126	          "\"--shared-mem-size\", \"{mmap_size}\", "
127	          "\"--shared-mem-base\", \"{mmap_base}\"]\n";
128	  json += "  },\n";
129	  json += "  \"result\": \"stderr:cycles\"\n";
130	  json += "}\n";
131	  fwrite(json.data(), 1, json.size(), stdout);
132	}
