145	static void print_help()
146	{
147	  print_version();
148	  fmt::print(R"(
149	Usage: sim_cpu_name [elf_file] [options]
150	
151	AndesCycle CPU simulator for RISC-V processors
152	
153	Argument:
154	  <elf_file>                  RISC-V ELF binary to simulate
155	
156	General:
157	  --help, -h                  Print this help message and exit
158	  --version                   Display version information and exit
159	  --print-config              Show CPU configuration and exit
160	  --print-qemu-config         Emit the QEMU -readconfig cfg (ISA from config.inc) and exit
161	  --describe                  Emit the andes-sim engine descriptor (JSON) and exit
162	  --print-memmap              Show memory map layout and exit
163	  --log-level <level>         Set logging verbosity [default: 2]
164	                              (0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off)
165	
166	Simulation:
167	  --mem-latency  <cycles>     Memory access latency in cycles [default: 1]
168	  --reset-vector <spec>       Set per-hart reset vector
169	                              <addr>        set all harts to <addr>
170	                              <hart>:<addr> set specific hart to <addr>
171	                              Overrides ELF entrypoint if specified
172	
173	Tracing:
174	  --pc-trace  <file>          Enable PC trace logging to CSV file
175	  --kanata    <file>          Enable Kanata pipeline visualization logging
176	  --clarity   <file>          Enable Clarity pipeline visualization logging
177	  --objdump   <file>          Load objdump disassembly for pipeline viewer labels
178	
179	Debug:
180	  --jtag-port <port>          JTAG remote bitbang port for OpenOCD [default: 9104]
181	
182	Extra Options (require additional license):
183	  --ilm       <image>         Load ILM ROM image
184	  --dlm       <image>         Load DLM ROM image
185	  --waveform  <file>          Enable VCD/FST waveform tracing
186	  --save                      Save context when CPU enters WFI
187	  --continue                  Restore context and resume execution
188	  --context-dir <dir>         Context directory [default: ./saved_ctx]
189	
190	Hybrid (QEMU + Verilator):
191	  --shared-mem-path <file>    mmap-backed file used as main RAM (zero-copy
192	                              shared with QEMU). Requires --shared-mem-size.
193	  --shared-mem-size <bytes>   Size of the shared mmap region; must cover the
194	                              full main memory range
195	  --shared-mem-base <hex>     Guest physical address that file offset 0 maps
196	                              to. Default 0x80000000 (QEMU virt RAM base);
197	                              override only for non-virt machine types.
198	  --resume-from-qemu <file>   Resume from a QEMU-side state snapshot.
199	                              Mutually exclusive with --continue.
200	  --handoff-out <file>        Drain architectural state to <file> when
201	                              `csrwi 0x7C0, 1` retires; exit with code 200.
202	  --hybrid-enter-pc <hex>     PC-trigger mode: orchestrator-side entry PC.
203	                              Accepted but IGNORED by vsim - entry is QEMU's
204	                              job (the plugin's `enter_pc=` arg). Logged for
205	                              symmetry with --hybrid-exit-pc.
206	  --hybrid-exit-pc <hex>      PC-trigger mode: drain when an insn at this PC
207	                              retires, instead of pre-scanning the ELF for
208	                              `csrwi 0x7C0, 1`. The binary need not contain
209	                              a magic CSR write.
210	  --drain-minimal             At the exit drain, read back only mcycle and
211	                              minstret (the cycle figure), passing every other
212	                              field through from the resume snapshot. Skips the
213	                              full register-file readback (~190 DM abstract
214	                              commands). Use when the drained state is not
215	                              verified; the driver sets it when --verify is off.
216	  --no-reset-baseline         Disable the liveness gate: restore every
217	                              transported register instead of skipping the ones
218	                              already at the engine's reset value. Also skips
219	                              the one-time reset-state capture + cache
220	                              ($XDG_CACHE_HOME/andesim) a first run performs.
221	)");
222	  // --ilm/--dlm: CPU-specific, not all CPUs have ILM/DLM
223	  // --waveform: requires compile flag VSIMDEBUG
224	  // --save/--continue/--context-dir: requires compile flag VSIMSAVABLE
225	}
