227	// F3 probe helpers -- kept OUT of the generic sc_main lambda so their
228	// structured-binding / iostream / fmt code is compiled once, not re-instantiated
229	// per CPU class (a per-CPU instantiation inside the generic lambda tripped a
230	// clang ICE).
231	static auto read_probe_list(const std::string& path) -> std::vector<uint16_t>
232	{
233	  std::ifstream pf{path};
234	  if (!pf)
235	    throw std::runtime_error("--probe: cannot open " + path);
236	  std::vector<uint16_t> addrs;
237	  for (std::string line; std::getline(pf, line);) {
238	    const auto b = line.find_first_not_of(" \t\r");
239	    if (b == std::string::npos || line[b] == '#') continue;
240	    addrs.push_back(
241	      static_cast<uint16_t>(std::stoul(line.substr(b), nullptr, 16)));
242	  }
243	  return addrs;
244	}
