246	static void emit_probe_csv(
247	  const std::vector<std::pair<uint16_t, std::optional<uint64_t>>>& results)
248	{
249	  for (const auto& r: results) {
250	    if (r.second)
251	      fmt::print("0x{:03X},yes,0x{:016x}\n", r.first, *r.second);
252	    else
253	      fmt::print("0x{:03X},no,-\n", r.first);
254	  }
255	}
