257	extern "C" auto sc_main(const int argc, char* argv[]) -> int
258	try {
259	  spdlog::set_default_logger(spdlog::stderr_color_mt("stderr_logger"));
260	  spdlog::set_pattern("[%^%l%$] %v");
261	
262	  const auto args = [&] {
263	    struct args
264	    {
265	      std::string pc_trace_file{};
266	      std::string elf_file{};
267	      std::optional<uint16_t> jtag_port = std::nullopt;
268	      bool memmap = false;
269	      std::string waveform_file{};
270	      unsigned mem_latency = 1;
271	      std::string ilm_file{};
272	      std::string dlm_file{};
273	      std::string kanata_file{};
274	      std::string objdump_file{};
275	      std::string clarity_file{};
276	      std::vector<std::string> reset_vectors{};
277	      bool continue_ctx = false;
278	      bool save_ctx = false;
279	      std::string context_dir = "./saved_ctx/";
280	      std::string shared_mem_path{};
281	      uint64_t shared_mem_size = 0;
282	      uint64_t shared_mem_base = 0x80000000;
283	      std::string resume_from_qemu{};
284	      std::string handoff_out{};
285	      std::optional<uint64_t> hybrid_enter_pc{};
286	      std::optional<uint64_t> hybrid_exit_pc{};
287	      bool drain_minimal = false;
288	      bool no_reset_baseline = false;
289	      std::string probe_list{};
290	      std::string transport_csrs{};
291	    } args;
292	
293	    const auto help_and_exit = [] {
294	      print_help();
295	      exit(0);
296	    };
297	
298	    auto p = parser{};
299	    p.shortflag('h', help_and_exit);
300	    p.longflag("help", help_and_exit);
301	    p.longflag("version", [] {
302	      print_version();
303	      exit(0);
304	    });
305	    p.longflag("print-memmap", [&] { args.memmap = true; });
306	    p.longflag("print-config", [] {
307	      print_cpu_configuration();
308	      exit(0);
309	    });
310	    p.longflag("print-qemu-config", [] {
311	      print_qemu_config();
312	      exit(0);
313	    });
314	    p.longflag("describe", [] {
315	      describe_engine();
316	      exit(0);
317	    });
318	    p.longopt("jtag-port", [&](const std::string_view s) {
319	      if (auto n = to_int<uint16_t>(s); n)
320	        args.jtag_port = *n;
321	      else
322	        throw std::runtime_error("invalid number for --jtag-port: "
323	                                 + std::string{s});
324	    });
325	    p.longopt("mem-latency", [&](const std::string_view s) {
326	      if (auto n = to_int<unsigned>(s); n)
327	        args.mem_latency = *n;
328	      else
329	        throw std::runtime_error("invalid number for --mem-latency: "
330	                                 + std::string{s});
331	    });
332	    p.longopt("log-level", [](const std::string_view s) {
333	      if (auto n = to_int<uint16_t>(s); n) {
334	        *n = std::min(*n, (uint16_t) SPDLOG_LEVEL_OFF);
335	        spdlog::set_level(static_cast<spdlog::level::level_enum>(*n));
336	      } else {
337	        throw std::runtime_error("invalid number for --log-level: "
338	                                 + std::string{s});
339	      }
340	    });
341	    p.longopt("waveform",
342	              [&](const std::string_view s) { args.waveform_file = s; });
343	    p.longopt("ilm", [&](const std::string_view s) { args.ilm_file = s; });
344	    p.longopt("dlm", [&](const std::string_view s) { args.dlm_file = s; });
345	    p.longopt("pc-trace",
346	              [&](const std::string_view s) { args.pc_trace_file = s; });
347	    p.longopt("kanata",
348	              [&](const std::string_view s) { args.kanata_file = s; });
349	    p.longopt("objdump",
350	              [&](const std::string_view s) { args.objdump_file = s; });
351	    p.longopt("clarity",
352	              [&](const std::string_view s) { args.clarity_file = s; });
353	    p.longflag("continue", [&] { args.continue_ctx = true; });
354	    p.longflag("drain-minimal", [&] { args.drain_minimal = true; });
355	    p.longflag("no-reset-baseline", [&] { args.no_reset_baseline = true; });
356	    p.longopt("probe", [&](const std::string_view s) { args.probe_list = s; });
357	    p.longopt("transport-csrs",
358	              [&](const std::string_view s) { args.transport_csrs = s; });
359	    p.longflag("save", [&] { args.save_ctx = true; });
360	    p.longopt("context-dir",
361	              [&](const std::string_view s) { args.context_dir = s; });
362	    p.longopt("shared-mem-path",
363	              [&](const std::string_view s) { args.shared_mem_path = s; });
364	    // Shared uint64 longopt handler: parse with 0x/0 prefixes, else throw a
365	    // uniform "invalid --<flag>". Replaces six identical try/catch blocks.
366	    auto u64_opt = [](const char* flag, auto& dest) {
367	      return [flag, &dest](std::string_view s) {
368	        try {
369	          dest = std::stoull(std::string{s}, nullptr, 0);
370	        } catch (...) {
371	          throw std::runtime_error(std::string{"invalid --"} + flag + ": "
372	                                   + std::string{s});
373	        }
374	      };
375	    };
376	    p.longopt("shared-mem-size", u64_opt("shared-mem-size", args.shared_mem_size));
377	    p.longopt("shared-mem-base", u64_opt("shared-mem-base", args.shared_mem_base));
378	    p.longopt("resume-from-qemu", [&](const std::string_view s) {
379	      args.resume_from_qemu = s;
380	    });
381	    p.longopt("handoff-out", [&](const std::string_view s) {
382	      args.handoff_out = s;
383	    });
384	    p.longopt("hybrid-enter-pc", u64_opt("hybrid-enter-pc", args.hybrid_enter_pc));
385	    p.longopt("hybrid-exit-pc", u64_opt("hybrid-exit-pc", args.hybrid_exit_pc));
386	    p.longopt("reset-vector", [&](const std::string_view s) {
387	      args.reset_vectors.emplace_back(s);
388	    });
389	    p.posarg([&](const std::string_view s) { args.elf_file = s; });
390	    p.parse(std::vector<std::string_view>(argv, argv + argc));
391	    return args;
392	  }();
393	
394	#ifndef VSIMSAVABLE
395	  if (args.save_ctx || args.continue_ctx || args.context_dir != "./saved_ctx/")
396	  {
397	    spdlog::critical(
398	      "--save, --continue, and --context-dir require VSIMSAVABLE build");
399	    std::exit(EXIT_FAILURE);
400	  }
401	#endif
402	
403	  if (!args.resume_from_qemu.empty() && args.continue_ctx)
404	    throw std::runtime_error(
405	      "--resume-from-qemu and --continue are mutually exclusive");
406	
407	  print_version();
408	
409	  // systemc and cci init
410	  auto broker = cci_utils::broker{"global_broker"};
411	  cci::cci_register_broker(broker);
412	
413	  const auto time_resolution = sc_core::sc_get_time_resolution();
414	  spdlog::debug("Using time resolution: {}", time_resolution.to_string());
415	
416	  std::optional<MmapBacking> shared_ram;
417	  if (!args.shared_mem_path.empty()) {
418	    if (args.shared_mem_size == 0)
419	      throw std::runtime_error(
420	        "--shared-mem-path requires --shared-mem-size > 0");
421	    shared_ram.emplace(args.shared_mem_path, args.shared_mem_size);
422	  } else if (args.shared_mem_size != 0) {
423	    throw std::runtime_error(
424	      "--shared-mem-size requires --shared-mem-path");
425	  }
426	
427	  // Hybrid mode: the mmap window is the only RAM; QEMU virt has no alias.
428	  const MemoryRegion ram_region = shared_ram
429	    ? MemoryRegion{args.shared_mem_base,
430	                   args.shared_mem_base + args.shared_mem_size - 1}
431	    : MemoryRegion{RAM_BASE, RAM_END};
432	  const MemoryRegion ram_alias_region = shared_ram
433	    ? MemoryRegion{SimpleMemory<32>::INVALID_ADDRESS,
434	                   SimpleMemory<32>::INVALID_ADDRESS}
435	    : MemoryRegion{RAM_ALIAS_BASE, RAM_ALIAS_END};
436	
437	  // run simulation
438	  const auto do_sim = [&]<typename CPU>() -> int {
439	    Simulator<CPU> sim{
440	      "sim",
441	      shared_ram ? shared_ram->span() : std::span<uint8_t>{},
442	      ram_region, ram_alias_region};
443	
444	    if (args.memmap) {
445	      sim.platform.interconnect.dump_region();
446	      return 0;
447	    }
448	
449	    sim.set_mem_latency(args.mem_latency);
450	
451	    if (!args.ilm_file.empty())
452	      sim.load_image(args.ilm_file, MEM_TYPE::ILM);
453	
454	    if (!args.dlm_file.empty())
455	      sim.load_image(args.dlm_file, MEM_TYPE::DLM);
456	
457	    // End of elaboration
458	    sc_core::sc_start(sc_core::SC_ZERO_TIME);
459	
460	    const auto t0 = std::chrono::steady_clock::now();
461	
462	    if (!args.waveform_file.empty())
463	      sim.enable_waveform(args.waveform_file);
464	
465	    if (!args.pc_trace_file.empty())
466	      sim.enable_pc_trace(args.pc_trace_file);
467	
468	    if (!args.kanata_file.empty() && !args.clarity_file.empty())
469	      throw std::runtime_error("--kanata and --clarity are mutually exclusive");
470	
471	    if (!args.kanata_file.empty())
472	      sim.enable_kanata(args.kanata_file, args.objdump_file);
473	
474	    if (!args.clarity_file.empty())
475	      sim.enable_clarity(args.clarity_file, args.objdump_file);
476	
477	    // In tier-2 hybrid resume, QEMU 1 already loaded the ELF into the
478	    // shared mmap. Re-loading would `std::fill_n(memsz - filesz, 0)` over
479	    // each PT_LOAD's .bss tail, wiping phase-1 writes to static buffers.
480	    // Still parse the ELF to set the reset vector -- between sim.reset()
481	    // and apply_resume_from_qemu's DMI halt, the hart fetches one or two
482	    // instructions from the reset vector; if that address is unmapped
483	    // the bus errors leave the hart in a state the resume cannot recover.
484	    const bool elf_already_in_shared_mmap =
485	      !args.resume_from_qemu.empty() && !args.shared_mem_path.empty();
486	    if (!args.elf_file.empty() && !args.continue_ctx)
487	      sim.load_elf(args.elf_file, /*skip_memory_load=*/elf_already_in_shared_mmap);
488	
489	    // Apply per-hart reset vector overrides (after load_elf sets defaults)
490	    for (const auto& s: args.reset_vectors) {
491	      auto [hart, addr] = parse_reset_vector(s);
492	      if (hart) {
493	        sim.set_reset_vector(*hart, addr);
494	      } else {
495	        for (size_t i = 0; i < sim.platform.reset_vector.size(); ++i)
496	          sim.set_reset_vector(i, addr);
497	      }
498	    }
499	
500	    if (args.continue_ctx)
501	      spdlog::info("You're resuming program from the given context");
502	
503	    if (args.jtag_port)
504	      sim.init_debug_port(args.jtag_port.value());
505	
506	    if (!args.jtag_port && args.elf_file.empty() && !args.continue_ctx
507	        && args.resume_from_qemu.empty())
508	      throw std::runtime_error(
509	        "Required arg : program, --jtag-port, or --resume-from-qemu");
510	
511	    if (args.continue_ctx || args.save_ctx) {
512	      std::string_view s = args.context_dir;
513	      if (std::filesystem::exists(s) && !std::filesystem::is_directory(s))
514	        throw std::runtime_error("Error: Path " + std::string{s}
515	                                 + " exists but is not a directory.");
516	      if (!std::filesystem::exists(s)) {
517	        try {
518	          std::filesystem::create_directories(s);
519	        } catch (const std::filesystem::filesystem_error& e) {
520	          throw std::runtime_error(std::string{"Failed to create directory: "}
521	                                   + e.what());
522	        }
523	      }
524	      sim.context_config = {args.save_ctx, args.continue_ctx, args.context_dir};
525	    }
526	
527	    // F6: drive the transport caps from the registered manifest's transported
528	    // set (--transport-csrs, hex addr per line) instead of config macros. Reuses
529	    // read_probe_list; andes_caps_from_transport_set rebuilds the exact caps.
530	    if (!args.transport_csrs.empty())
531	      sim.set_transport_caps(
532	        hybrid::andes_caps_from_transport_set(read_probe_list(args.transport_csrs)));
533	
534	    sim.reset();
535	
536	    // F3: --probe <addr-list-file>. Halt the freshly-reset hart and checked-read
537	    // each CSR address -> CSV "0xADDR,yes|no,0xRESET" on stdout, then exit (no
538	    // resume, no run). Existence + reset values MEASURED on the live RTL, for
539	    // gen_manifest.py. Needs a (spin) ELF so the reset vector is mapped. The
540	    // list-read + CSV-emit live in free functions so their code is not
541	    // re-instantiated per CPU class (avoids a clang ICE).
542	    if (!args.probe_list.empty()) {
543	      emit_probe_csv(sim.probe_csrs(read_probe_list(args.probe_list)));
544	      return 0;
545	    }
546	
547	    if (!args.resume_from_qemu.empty()) {
548	      // LG3: reset-baseline cache key = engine binary identity + ELF
549	      // identity (the hart free-runs a few workload instructions between
550	      // reset and the DMI halt, so the halted state is per-ELF; see
551	      // hybrid/reset_baseline.hpp). Empty path -> liveness gate off.
552	      std::string baseline_cache{};
553	      struct stat sim_bin{}, elf_bin{};
554	      if (const auto root = hybrid::reset_baseline_cache_root(
555	            std::getenv("XDG_CACHE_HOME"), std::getenv("HOME"));
556	          !args.no_reset_baseline && !root.empty() && !args.elf_file.empty()
557	          && ::stat("/proc/self/exe", &sim_bin) == 0
558	          && ::stat(args.elf_file.c_str(), &elf_bin) == 0) {
559	        baseline_cache =
560	          (root
561	           / hybrid::reset_baseline_file_name(
562	               std::filesystem::path(argv[0]).filename().string(),
563	               ANDESCYCLE_VERSION, uint64_t(sim_bin.st_mtime),
564	               uint64_t(sim_bin.st_size), uint64_t(elf_bin.st_mtime),
565	               uint64_t(elf_bin.st_size)))
566	            .string();
567	      }
568	      sim.apply_resume_from_qemu(args.resume_from_qemu, baseline_cache);
569	    }
570	
571	    if (args.hybrid_enter_pc)
572	      spdlog::warn("--hybrid-enter-pc=0x{:x} ignored: entry trigger is "
573	                   "QEMU's job (use plugin enter_pc= arg)",
574	                   *args.hybrid_enter_pc);
575	
576	    if (!args.handoff_out.empty())
577	      sim.enable_hybrid_handoff(args.elf_file, args.handoff_out,
578	                                args.hybrid_exit_pc, args.drain_minimal);
579	
580	    const int exit_code = sim.run();
581	
582	    sim.cpu.final();
583	
584	    const auto t1 = std::chrono::steady_clock::now();
585	    const auto cycles = sim.get_cycles();
586	    spdlog::info("{} cycles simulated", cycles);
587	    if (cycles > 0) {
588	      const auto ms =
589	        std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0);
590	      spdlog::info("{}.{:03}s elapsed, {:.3f}Hz", ms.count() / 1000,
591	                   ms.count() % 1000,
592	                   double(cycles) / double(ms.count()) * 1000.0);
593	    }
594	    return exit_code;
595	  };
596	
597	  return do_sim.operator()<VSIM_CPU_INTERFACE_CLASS>();
598	
599	} catch (const std::exception& e) {
600	  spdlog::critical("fatal exception: {}\n", e.what());
601	  std::exit(EXIT_FAILURE);
602	} catch (...) {
603	  std::terminate();
604	}
