31	  auto make_axi_to_tlm(const char* name, auto& bfm_socket)
32	    -> std::unique_ptr<axi_to_tlm_bridge<bus_width>>
33	  {
34	    auto bridge = std::make_unique<axi_to_tlm_bridge<bus_width>>(name);
35	    bridge->pe.clk_i.bind(platform.clk);
