85	  Simulator(const sc_core::sc_module_name& name)
86	      : sc_core::sc_module{name}, dtm(platform.dtm)
87	  {
88	    cpu.bind(platform.clk, platform.resetn, platform.reset_vector,
89	             platform.dmi_signals, platform.wfi_signal, platform.int_trigger);
90	
91	    // --- CPU memory BFM → interconnect ---
92	    if constexpr (is_axi) {
93	      mem_bridge = make_axi_to_tlm("mem_bridge", cpu.mem_bfm.isckt);
94	      platform.interconnect.bind_initiator(mem_bridge->tlm_isck);
95	    } else {
96	      platform.interconnect.bind_initiator(cpu.mem_bfm.isckt);
97	    }
98	
99	    // --- CPU MMIO BFM → interconnect ---
100	    if constexpr (requires { cpu.mmio_bfm; }) {
101	      if constexpr (is_axi) {
102	        mmio_bridge = make_axi_to_tlm("mmio_bridge", cpu.mmio_bfm.isckt);
103	        platform.interconnect.bind_initiator(mmio_bridge->tlm_isck);
104	      } else {
105	        platform.interconnect.bind_initiator(cpu.mmio_bfm.isckt);
106	      }
107	    }
108	
109	    // --- CPU HVM subordinate port ---
110	    if constexpr (requires { cpu.hvm_bfm; }) {
111	      if constexpr (is_axi) {
112	        hvm_bridge = make_tlm_to_axi("hvm_bridge", cpu.hvm_bfm.tsckt);
113	        platform.interconnect.bind_target(
114	          hvm_bridge->tlm_tsck,
115	          {CPU::NDS_HVM_BASE,
116	           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
117	      } else {
118	        platform.interconnect.bind_target(
119	          cpu.hvm_bfm.tsckt,
120	          {CPU::NDS_HVM_BASE,
121	           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
122	      }
123	      platform.custom_master.hvm_base = CPU::NDS_HVM_BASE;
124	    }
125	
126	    // --- CPU slave port ---
127	    if constexpr (requires { cpu.slv_bfm; }) {
128	      if constexpr (is_axi) {
129	        slv_bridge = make_tlm_to_axi("slv_bridge", cpu.slv_bfm.tsckt);
130	        platform.interconnect.bind_target(slv_bridge->tlm_tsck,
131	                                          {HART0_ILM_BASE, HART0_DLM_END});
132	      } else {
133	        platform.interconnect.bind_target(cpu.slv_bfm.tsckt,
134	                                          {HART0_ILM_BASE, HART0_DLM_END});
135	      }
136	      platform.custom_master.ilm_base = HART0_ILM_BASE;
137	      platform.custom_master.dlm_base = HART0_DLM_BASE;
138	    }
139	
140	    // --- CPU sys bus (slave port, 64-bit) → interconnect ---
141	    if constexpr (requires { cpu.sys_bfm; }) {
142	      sys_adapter =
143	        std::make_unique<socket_width_adapter<bus_width, sys_bus_width>>(
144	          "sys_adapter");
145	      sys_bridge =
146	        std::make_unique<tlm_to_axi_bridge<sys_bus_width>>("sys_bridge");
147	      sys_bridge->pe.clk_i.bind(platform.clk);
148	      sys_bridge->axi_isck.bind(cpu.sys_bfm.tsckt);
149	      sys_adapter->isck.bind(sys_bridge->tlm_tsck);
150	      platform.interconnect.bind_target(sys_adapter->tsck,
151	                                        {MLIF_BASE, SLIF_END});
152	    }
153	
154	#if _NDS_IOCP_NUM > 0
155	    iocp_master.protocol_engine.clk_i.bind(platform.clk);
156	    iocp_master.socket.bind(cpu.iocp_bfm.tsckt);
157	#endif // _NDS_IOCP_NUM
158	  }
