  // skip_memory_load: parse the ELF and set the reset vector, but leave
  // platform.main_memory untouched. Used in tier-2 hybrid resume where
  // QEMU 1's -kernel already populated the shared mmap; re-loading would
  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
  // to static buffers. The reset vector is still set so the hart has a
  // valid fetch target during the post-reset cycles that precede the DMI
  // halt+DPC-write resume sequence.
  void load_elf(const std::string& path, bool skip_memory_load = false)
  {
    const auto elf = LIEF::ELF::Parser::parse(path);
    if (!elf) {
      spdlog::critical("Check if it's a valid ELF file path : {}", path);
      exit(1);
    }

    if (!skip_memory_load)
      read_elf_into_memory(
        *elf,
        static_cast<xlen_t>(platform.main_memory.region.base_address),
        platform.main_memory.data);
    for (auto& rv: platform.reset_vector)
      rv.write(elf->entrypoint());
  }

